# ---------------------------------------------------------------- 7-сабақ
CB = ("class Breaker:\n"
      "    \"\"\"closed -> (threshold қатарынан сәтсіздік) -> open -> (cooldown өтті) -> half-open -> (сынақ сәтті) -> closed\"\"\"\n"
      "    def __init__(self, threshold=3, cooldown=10):\n"
      "        self.state, self.fails, self.opened_at = 'closed', 0, None\n"
      "        self.threshold, self.cooldown = threshold, cooldown\n"
      "    def allow(self, now):\n"
      "        if self.state == 'open' and now - self.opened_at >= self.cooldown:\n"
      "            self.state = 'half-open'           # бір сынақ сұрауына рұқсат\n"
      "            return True\n"
      "        return self.state == 'closed'\n"
      "    def record(self, ok, now):\n"
      "        if ok:\n"
      "            self.state, self.fails = 'closed', 0\n"
      "        else:\n"
      "            self.fails += 1\n"
      "            if self.state == 'half-open' or self.fails >= self.threshold:\n"
      "                self.state, self.opened_at = 'open', now\n\n"
      "b = Breaker()\n"
      "dependency_up_from = 25         # тәуелділік 25-секундтан бастап қалпына келеді\n"
      "sent = 0\n"
      "for t in range(0, 40, 2):\n"
      "    if b.allow(t):\n"
      "        sent += 1\n"
      "        b.record(t >= dependency_up_from, t)\n"
      "        print(f't={t:2}: жіберілді -> {b.state}')\n"
      "print('жіберілген сұраулар:', sent, '/ 20')")

