QUEUE = ("import random\n\n"
         "def mm1(lam, mu, n, seed=1):\n"
         "    \"\"\"M/M/1 кезегінің симуляциясы: келу λ, қызмет μ (секундына)\"\"\"\n"
         "    rng = random.Random(seed)\n"
         "    t = free_at = 0.0\n"
         "    total_wait = 0.0\n"
         "    for _ in range(n):\n"
         "        t += rng.expovariate(lam)\n"
         "        start = max(t, free_at)\n"
         "        free_at = start + rng.expovariate(mu)\n"
         "        total_wait += free_at - t          # кезек + қызмет\n"
         "    return total_wait / n\n\n"
         "mu = 100   # сервер секундына 100 сұрау өңдейді\n"
         "for rho in (0.5, 0.8, 0.9, 0.95):\n"
         "    lam = rho * mu\n"
         "    W_theory = 1 / (mu - lam)\n"
         "    W_sim = mm1(lam, mu, 2000)\n"
         "    print(f'жүктеме ρ = {rho:4}: W теория {1000 * W_theory:6.1f} мс, симуляция {1000 * W_sim:6.1f} мс, L = λW = {lam * W_theory:5.1f} сұрау жүйеде')")

