CHAOS = ("import math, random\n\n"
         "def run(n, p_fail, rng):\n"
         "    return sum(rng.random() < p_fail for _ in range(n))\n\n"
         "rng = random.Random(9)\n"
         "n = 4000\n"
         "control = run(n, 0.002, rng)          # қалыпты топ\n"
         "experiment = run(n, 0.002, rng)       # бір реплика өшірілген топ (гипотеза: әсер жоқ)\n"
         "p1, p2 = control / n, experiment / n\n"
         "p = (control + experiment) / (2 * n)\n"
         "se = math.sqrt(p * (1 - p) * 2 / n)\n"
         "z = (p2 - p1) / se if se else 0.0\n"
         "print(f'бақылау: {control} қате, эксперимент: {experiment} қате, z = {z:.2f}')\n"
         "print('тұрақты күй гипотезасы:', 'жоққа шығарылмады' if abs(z) < 1.96 else 'жоққа шығарылды - әсер бар')\n\n"
         "# Үшеу ережесі: 0 сәтсіздік байқалса, 95% сенімділікпен p < 3/n\n"
         "for m in (100, 1000, 3000):\n"
         "    exact = 1 - 0.05 ** (1 / m)\n"
         "    print(f'{m:5} сәтті сынақ: p < {exact:.5f} (≈ 3/n = {3 / m:.5f})')")

